if __name__ == "__main__":
    claimed_representatives = representatives
    claimed_implications = implications
    non_implications = {i: set() for i in range(1, 991)}
    implications = {i: set() for i in range(1, 991)}
    to_rep = {}
    for i, eqi in enumerate(eq_list):
        if i == 0:
            continue
        iterate_up_to = len(models(extra0=op_declare+"assign(max_models, 15). assign(iterate_up_to, 8).", extra1=quasigroup_eqs + eqi + ".")[-1])
        for j, eqj in enumerate(eq_list):
            if j == 0:
                continue
            print(f"Eq{i} {eqi} =>? Eq{j} {eqj}", end='\r')
            if models(extra0=op_declare+f"assign(iterate_up_to, {iterate_up_to}). assign(selection_measure, 3).", extra1=quasigroup_eqs + eqi + ".", extra2=eqj + "."):
                non_implications[i].add(j)
            elif prove(extra0=op_declare, extra1=quasigroup_eqs + eqi + ".", extra2=eqj + "."):
                implications[i].add(j)
                if i > j and i in implications[j]:
                    to_rep[i] = j
                    implications[i] = set(implications[j])
                    non_implications[i] = set(non_implications[j])
                    break
            elif models(extra0=op_declare+"assign(selection_measure, 3).", extra1=quasigroup_eqs + eqi + ".", extra2=eqj + ".", max_seconds=10):
                non_implications[i].add(j)
        if i not in to_rep:
            to_rep[i] = i
        if len(implications[i]) + len(non_implications[i]) < 990:
            for j in sorted(set(range(1, 991)).difference(implications[i]).difference(non_implications[i])):
                print(f"Unknown implication from Sch-{i} {eqi} to Sch-{j} {eq_list[j]}")

    representatives = sorted(set(to_rep.values()))
    if claimed_representatives != representatives:
        print(f"Announced representatives {claimed_representatives} differs from computed {representatives}")
    implications = {i: implications[i].intersection(representatives) for i in representatives}
    if claimed_implications != implications:
        print(claimed_implications)
        print("differs from computed")
        print(implications)

    print("representatives and equivalence classes:")
    print(representatives)
    computed_class_list = [(i, sorted(set(j for j in range(1, 991) if to_rep[j] == i))) for i in representatives]
    if computed_class_list != class_list:
        print("Unexpectedly")
        print(class_list)
        print("differs from computed")
        print(computed_class_list)

    with open("quasigroup-representatives.txt", "w") as f:
        for i in representatives:
            print(f"Sch-{i}: {eq_list[i]}", file=f)

    with open("quasigroup-classes.txt", "w") as f:
        for i in representatives:
            print(f"Sch-{i} class {[j for j in range(1, 991) if to_rep[j] == i]}", file=f)

    with open("quasigroup-implications.txt", "w") as f:
        for i in representatives:
            print(f"Sch-{i}: {eq_list[i]} ⇒ {implications[i]}", file=f)
